// BFS: shortest number of hops from start to target
int hops(String start, String target) {
    Deque<String> queue = new ArrayDeque<>(List.of(start));
    Map<String, Integer> dist = new HashMap<>(Map.of(start, 0));
    while (!queue.isEmpty()) {
        String node = queue.poll();
        if (node.equals(target)) return dist.get(node);
        for (String next : dependsOn.getOrDefault(node, List.of())) {
            if (dist.putIfAbsent(next, dist.get(node) + 1) == null) queue.offer(next);
        }
    }
    return -1;
}

hops("checkout", "stock");   // 2

// WRONG: no visited set — A -> B -> A -> B ...
