    for (String next : graph.get(node)) dfs(next);
}

// RIGHT
void dfs(String node, Set<String> visited) {
    if (!visited.add(node)) return;          // already seen
    for (String next : graph.get(node)) dfs(next, visited);
}

// Two pointers: does a sorted array have a pair summing to target? O(n)
boolean hasPair(int[] sorted, int target) {
    int lo = 0, hi = sorted.length - 1;
    while (lo < hi) {
        int sum = sorted[lo] + sorted[hi];
        if (sum == target) return true;
        if (sum < target) lo++; else hi--;
    }
    return false;
}

// Sliding window: longest substring without repeated characters. O(n)
int longestUnique(String s) {
    Map<Character, Integer> lastSeen = new HashMap<>();
    int best = 0;
    for (int left = 0, right = 0; right < s.length(); right++) {
        Integer prev = lastSeen.put(s.charAt(right), right);
        if (prev != null && prev >= left) left = prev + 1;   // shrink past the repeat
        best = Math.max(best, right - left + 1);
    }
    return best;
}

