// Fewest coins for an amount (coins = {1, 5, 10, 25}), bottom-up. O(amount × coins)
int minCoins(int[] coins, int amount) {
    int[] best = new int[amount + 1];
    Arrays.fill(best, Integer.MAX_VALUE);
    best[0] = 0;                                         // base case
    for (int a = 1; a <= amount; a++) {
        for (int c : coins) {
            if (c <= a && best[a - c] != Integer.MAX_VALUE) {
                best[a] = Math.min(best[a], best[a - c] + 1);
            }
        }
    }
    return best[amount] == Integer.MAX_VALUE ? -1 : best[amount];
}

minCoins(new int[]{1, 5, 10, 25}, 30);   // 2  (25 + 5)

// WRONG: recursive computeIfAbsent
long fib(int n) {
    if (n < 2) return n;
    return memo.computeIfAbsent(n, k -> fib(k - 1) + fib(k - 2));   // ConcurrentModificationException
}

// RIGHT
long fib(int n) {
    if (n < 2) return n;
    Long cached = memo.get(n);
    if (cached != null) return cached;
    long result = fib(n - 1) + fib(n - 2);
    memo.put(n, result);
    return result;
}

